package com.gestourant.catalog;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String name; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Column(nullable=false) private Integer stock; @Column(nullable=false) private boolean active=true; protected Product(){} public Product(String n,BigDecimal p,Integer s){name=n;price=p;stock=s;} public Long getId(){return id;} public String getName(){return name;} public BigDecimal getPrice(){return price;} public Integer getStock(){return stock;} public boolean isActive(){return active;} public void update(String n,BigDecimal p,Integer s,boolean a){name=n;price=p;stock=s;active=a;} public void reduceStock(int q){if(stock<q)throw new IllegalArgumentException("Inventario insuficiente para " + name);stock-=q;} }
